class Solution:
    def sortPeople(self, names: list[str], heights: list[int]) -> list[str]:
        combined = sorted(zip(heights, names), key=lambda x: x[0], reverse=True)
        return [name for _, name in combined]

class Solution {
public:
    std::vector<std::string> sortPeople(std::vector<std::string>& names, std::vector<int>& heights) {
        int n = names.size();
        std::vector<std::pair<int, std::string>> people(n);
        for (int i = 0; i < n; i++) {
            people[i] = {heights[i], names[i]};
        }
        std::sort(people.begin(), people.end(), [](const auto& a, const auto& b) {
            return a.first > b.first;
        });
        std::vector<std::string> res(n);
        for (int i = 0; i < n; i++) res[i] = people[i].second;
        return res;
    }
};

class Solution {
    public String[] sortPeople(String[] names, int[] heights) {
        int n = names.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) -> Integer.compare(heights[b], heights[a]));
        String[] res = new String[n];
        for (int i = 0; i < n; i++) res[i] = names[idx[i]];
        return res;
    }
}

var sortPeople = function(names, heights) {
    return names
        .map((name, i) => ({ name, height: heights[i] }))
        .sort((a, b) => b.height - a.height)
        .map(p => p.name);
};
